// exec deletes the rows, with their join table rows, in one transaction, and
// returns how many there were.
pub fn (b ArticleDelete) exec() !int {
	return b.graph.client.delete(b.data)
}

// articles_by_keys returns the rows with the keys `keys`, in their order.
fn (g Graph) articles_by_keys(keys []string) ![]ArticleNode {
	// as stored: no privacy rule or interceptor hides a row just written
	rows := Graph{
		client: g.client.bypass()
	}.articles().where(load.in_keys('id', keys, .i64)).all()!
	mut by_key := map[string]ArticleNode{}
	for row in rows {
		by_key[row.article.id.str()] = row
	}
	mut found := []ArticleNode{cap: keys.len}
	for key in keys {
		found << by_key[key] or {
			return NotFoundError{
				table: 'articles'
			}
		}
	}
	return found
}

// CreateArticleInput is what a create of a `articles` row sets, as the GraphQL input
// `CreateArticleInput` gives it: `none` and empty lists leave things as
// they are.
pub struct CreateArticleInput {
pub mut:
	created_at ?time.Time
	updated_at ?time.Time
	user_id    ?i64
	title      ?string
	status     ?models.Status
	views      ?int
	deleted_at ?time.Time
	tag_ids    []int
}

// set_input sets what `input` gives: clears first, then values, then edges.
pub fn (b ArticleCreate) set_input(input CreateArticleInput) ArticleCreate {
	mut next := b
	if v := input.created_at {
		next = next.set_created_at(v)
	}
	if v := input.updated_at {
		next = next.set_updated_at(v)
	}
	if v := input.user_id {
		next = next.set_user_id(v)
	}
	if v := input.title {
		next = next.set_title(v)
	}
	if v := input.status {
		next = next.set_status(v)
	}
	if v := input.views {
		next = next.set_views(v)
	}
	if v := input.deleted_at {
		next = next.set_deleted_at(v)
	}
	if input.tag_ids.len > 0 {
		next = next.add_tags_ids(...input.tag_ids)
	}
	return next
}

